import type { EntityInput, Kind } from "@/lib/schema";

/**
 * Records that were the same thing under two ids, and the id each was merged into.
 *
 * The corpus grows two ways: an editor writes a record by hand, and a fetcher ingests one from a registry or a
 * literature API. Both reach the same paper and the same study, and when they do the corpus held it twice, each copy
 * with its own published URL. The rule, and the procedure for merging a new pair, are in docs/DUPLICATE-RECORDS.md;
 * the merge itself is `npx tsx scripts/merge-records.ts <survivor> <retired> "<reason>"`.
 *
 * Three things hang off this file:
 *   - MERGE_SUPPLEMENTS carries what the retired record added and the survivor lacked: relations, links, aliases and
 *     gap-filling scalars. Applied by src/data/index.ts the way a spike supplement is (arrays append and
 *     de-duplicate, scalars fill gaps only), so no link is lost when a record is retired.
 *   - src/lib/corpus-rules.test.ts checks that every retired id has a redirect in vercel.json, that no retired id is
 *     still a live record, and that no two papers share a DOI or a PubMed id.
 *   - vercel.json redirects the retired page to the survivor, and scripts/build-redirect-stubs.ts writes the static
 *     stub that does the same on any host, because the retired URL is published and indexed.
 *
 * Nothing here is a deletion: the retired record's own text is in the git history, and the survivor carries its
 * relations. Do not remove an entry; the redirect and the ratchet both read it.
 */
export type MergedRecord = {
  /** The id that no longer has a record. Its URL redirects to the survivor's. */
  retired: string;
  /** The id that kept the page. */
  survivor: string;
  kind: Kind;
  /** The date the merge landed. */
  merged: string;
  /** Why the two were one thing: the shared DOI, PubMed id or registry id, and which side was the fetcher's. */
  reason: string;
};

/** A partial record merged onto the survivor: what the retired record carried and the survivor did not. */
export type MergeSupplement = { id: string; kind: Kind } & Partial<Record<string, unknown>>;

/** Built on first use, because the arrays themselves are written at the end of this file by the merge script. */
let byId: Map<string, MergeSupplement[]> | undefined;
const applied = new Set<string>();
function supplementsById(): Map<string, MergeSupplement[]> {
  if (!byId) {
    byId = new Map();
    for (const s of MERGE_SUPPLEMENTS) byId.set(s.id, [...(byId.get(s.id) ?? []), s]);
  }
  return byId;
}

/** Merge every supplement for this entity: arrays append and de-duplicate, scalars fill gaps only. */
export function applyMergeSupplements(e: EntityInput): EntityInput {
  const list = supplementsById().get(e.id);
  if (!list) return e;
  applied.add(e.id);
  const out: Record<string, unknown> = { ...e };
  for (const sup of list) {
    for (const [k, v] of Object.entries(sup)) {
      if (k === "id" || k === "kind" || v === undefined) continue;
      if (Array.isArray(v)) {
        const have = (out[k] as unknown[] | undefined) ?? [];
        out[k] = [...have, ...v.filter((x) => !have.some((y) => JSON.stringify(y) === JSON.stringify(x)))];
      } else if (out[k] === undefined) out[k] = v;
    }
  }
  return out as EntityInput;
}

/** Supplement ids that matched no record: the survivor disappeared, which would lose the retired record's relations. */
export function unappliedMergeSupplements(): string[] {
  return [...supplementsById().keys()].filter((id) => !applied.has(id));
}

